/* The panel's icon set: Phosphor glyphs as inline SVG (admin/glyphs.ts, generated by scripts/icons.mjs). Regular
   weight for controls; duotone, with its faint fill, for navigation and tiles. Directional icons mirror in RTL. */
import type { CSSProperties } from 'react';
import { ADMIN_GLYPHS, type Glyph } from '../glyphs';

export type AIconName = keyof typeof ADMIN_GLYPHS;
// Only arrows that mean "back", "forward" or "out" are mirrored. The caret icons (left/right) are already chosen by
// their physical direction in this right-to-left panel, and the trend arrows sit next to left-to-right charts.
const DIRECTIONAL = new Set<AIconName>(['back', 'next', 'external', 'logout', 'send', 'undo']);

export function AIcon({ name, duo, size, className, style, label }: {
  name: AIconName; duo?: boolean; size?: number; className?: string; style?: CSSProperties; label?: string;
}) {
  const g: Glyph = ADMIN_GLYPHS[name];
  const shape = (duo && g.duotone) || g.light;
  return (
    <svg className={`ic${DIRECTIONAL.has(name) ? ' flip' : ''}${className ? ' ' + className : ''}`} viewBox="0 0 256 256" width="1em" height="1em" fill="currentColor"
      aria-hidden={label ? undefined : true} role={label ? 'img' : undefined} aria-label={label} focusable="false" style={size ? { fontSize: size, ...style } : style}>
      {shape.map(([d, opacity], i) => <path key={i} d={d} opacity={opacity} />)}
    </svg>
  );
}
